// ═══ anyOf PITFALL: first completion may be failure! ═══
CF<Object> first = CompletableFuture.anyOf(
    supplyAsync(() -> { throw new RuntimeException("Bureau-1 down!"); }),  // fails fast!
        supplyAsync(() -> { sleep(200);
        return 750; }),  // succeeds but slower
        supplyAsync(() -> { sleep(400);
        return 720; })   // succeeds but slowest
);
// anyOf returns Bureau-1's failure (first to complete!)
// Bureau-2 would have succeeded — but anyOf already completed with error!

// ═══ RACE-ON-SUCCESS: first SUCCESS wins ═══
public static <T> CompletableFuture<T> raceOnSuccess(
        List<CompletableFuture<T>> futures, long timeoutMs) {

    CompletableFuture<T> result = new CompletableFuture<>();
    AtomicInteger remaining = new AtomicInteger(futures.size());

    for (CompletableFuture<T> cf : futures) {
        cf.whenComplete((value, ex) -> {
            if (ex == null) {
                // SUCCESS! Complete the result CF (first success wins)
                if (result.complete(value)) {
                    // Cancel remaining futures (save resources!)
                    futures.forEach(f -> f.cancel(true));
                }
            } else {
                // FAILURE: decrement remaining
                if (remaining.decrementAndGet() == 0 && !result.isDone()) {
                    // ALL failed! Complete with last error.
                    result.completeExceptionally(ex);
                }
            }
        });
    }

    // Timeout: if no success within deadline
    result.orTimeout(timeoutMs, TimeUnit.MILLISECONDS);
    return result;
}

// Usage:
CF<Integer> score = raceOnSuccess(List.of(
    supplyAsync(() -> callBureau1(), ioPool),
    supplyAsync(() -> callBureau2(), ioPool),
    supplyAsync(() -> callBureau3(), ioPool)
), 500);  // 500ms deadline!

// Bureau-1 fails (10ms) → ignored
// Bureau-2 succeeds (200ms) → result completed! Bureau-3 cancelled!
// Total: 200ms latency, 3× backend calls
