// ─── File: src/test/java/com/bank/race/RaceOnSuccessTest.java ───
package com.bank.race;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class RaceOnSuccessTest {

    static <T> CompletableFuture<T> raceOnSuccess(
            List<CompletableFuture<T>> futures, long timeoutMs) {
        CompletableFuture<T> result = new CompletableFuture<>();
        AtomicInteger remaining = new AtomicInteger(futures.size());

        for (CompletableFuture<T> cf : futures) {
            cf.whenComplete((value, ex) -> {
                if (ex == null) {
                    if (result.complete(value)) {
                        futures.forEach(f -> f.cancel(true));
                    }
                } else if (remaining.decrementAndGet() == 0 && !result.isDone()) {
                    result.completeExceptionally(ex);
                }
            });
        }
        result.orTimeout(timeoutMs, TimeUnit.MILLISECONDS);
        return result;
    }

    void sleep(long ms) { try { Thread.sleep(ms); } catch (InterruptedException e) {} }

    // ═══ anyOf pitfall: returns first failure ═══
    @Test
    void anyOf_returnsFirstFailure() {
        CompletableFuture<Object> first = CompletableFuture.anyOf(
            CompletableFuture.supplyAsync(() -> { throw new RuntimeException("Fast fail!"); }),
                CompletableFuture.supplyAsync(() -> { sleep(200);
                return 750; })
        );

        assertThatThrownBy(first::join).isInstanceOf(CompletionException.class);
        // Returned failure! Even though second would succeed!
    }

    // ═══ raceOnSuccess: returns first SUCCESS ═══
    @Test
    void raceOnSuccess_returnsFirstSuccess() throws Exception {
        CompletableFuture<Integer> result = raceOnSuccess(List.of(
            CompletableFuture.supplyAsync(() -> { throw new RuntimeException("Bureau-1 down!"); }),
                CompletableFuture.supplyAsync(() -> { sleep(200);
                return 750; }),
                CompletableFuture.supplyAsync(() -> { sleep(400);
                return 720; })
        ), 5000);

        assertThat(result.get()).isEqualTo(750);  // first SUCCESS! Not the failure!
    }

    // ═══ raceOnSuccess: all fail → exception ═══
    @Test
    void raceOnSuccess_allFail() {
        CompletableFuture<Integer> result = raceOnSuccess(List.of(
            CompletableFuture.supplyAsync(() -> { throw new RuntimeException("Fail-1"); }),
            CompletableFuture.supplyAsync(() -> { throw new RuntimeException("Fail-2"); })
        ), 5000);

        assertThatThrownBy(result::join).isInstanceOf(CompletionException.class);
    }

    // ═══ raceOnSuccess: timeout → TimeoutException ═══
    @Test
    void raceOnSuccess_timeout() {
        CompletableFuture<Integer> result = raceOnSuccess(List.of(
                CompletableFuture.supplyAsync(() -> { sleep(5000);
                return 750; })
        ), 200);  // 200ms deadline!

        assertThatThrownBy(result::join)
            .isInstanceOf(CompletionException.class)
            .hasCauseInstanceOf(TimeoutException.class);
    }
}
